import{_ as n,I as s,o as l,c as h,a6 as o,J as a,j as e,a as i}from"./chunks/framework.9ylqSDY5.js";const b=JSON.parse('{"title":"Night Studio","description":"","frontmatter":{"title":"Night Studio","visibility":"public","audience":"astronomer","tier":"guide","source":"handwritten"},"headers":[],"relativePath":"guides/observing/night-studio.md","filePath":"guides/observing/night-studio.md"}'),d={name:"guides/observing/night-studio.md"};function g(u,t,p,c,m,f){const r=s("ToolShot");return l(),h("div",null,[t[0]||(t[0]=o('<h1 id="night-studio" tabindex="-1">Night Studio <a class="header-anchor" href="#night-studio" aria-label="Permalink to “Night Studio”">​</a></h1><blockquote><p>Powerful visualisations to prepare your observations.</p></blockquote><p><strong>Night Studio</strong> is where you prepare your observations: decide what to observe, when and from where, for any type of target, moving or not, and build the target lists and finding charts you take to the <a href="./control-room">Control Room</a>.</p><h2 id="night-explorer" tabindex="-1">Night Explorer <a class="header-anchor" href="#night-explorer" aria-label="Permalink to “Night Explorer”">​</a></h2><p>Decide what to observe tonight, or find the best night of the year for a target. The Night Explorer (also known as iObserve) puts up to six panes side by side, all on the same targets, site and night.</p>',5)),a(r,{tool:"night-explorer"}),t[1]||(t[1]=o('<ul><li><strong>Views</strong>: airmass and altitude curves, star tracks, sky maps, finding charts, and annual charts. Each pane shows the one you choose.</li><li><strong>Curves</strong>: besides airmass, the parallactic angle, the azimuth and the distance to the Moon.</li><li><strong>Targets</strong>: deep-sky objects, exoplanets, planets, asteroids and comets, near-Earth object candidates, microlensing events and transients. Import them by name, from a catalogue, a file, a target list or an Aladin view.</li><li><strong>Your own tree</strong>: targets are arranged in folders that are yours alone. The targets themselves are shared with the members of your observatory.</li><li><strong>Output</strong>: print or export the plots.</li></ul><h2 id="transit-browser" tabindex="-1">Transit Browser <a class="header-anchor" href="#transit-browser" aria-label="Permalink to “Transit Browser”">​</a></h2><p>Find the exoplanet transits you can observe from your site on a given night.</p>',3)),a(r,{tool:"transit-browser"}),t[2]||(t[2]=o('<ul><li><strong>Known planets</strong> come from the NASA Exoplanet Archive. Filter them by period, depth, duration, radius and more, then jump to the next night with a transit.</li><li><strong>Your own targets</strong> can be shown with their next transits, ten per target.</li><li><strong>Custom transits</strong> can be attached to any target, exoplanet or not, by giving a midpoint, a duration and, optionally, a period and a depth.</li><li>Each transit is drawn over the airmass curves of its night, to see at once whether it happens high enough in the dark.</li></ul><h2 id="target-lists" tabindex="-1">Target Lists <a class="header-anchor" href="#target-lists" aria-label="Permalink to “Target Lists”">​</a></h2><p>Group targets by interest or programme, and find them again in the other tools.</p>',3)),a(r,{tool:"target-lists"}),t[3]||(t[3]=o('<p>Lists are read by the Night Explorer, the <a href="./observer-console">Observer Console</a> and the <a href="./night-scheduler">Night Scheduler</a>. Import targets into a list, export it, or fill it from a script with the <a href="/reference/python-resources#target-lists">Python module</a>. One list is the default: the targets you add go there.</p><h2 id="transient-sky" tabindex="-1">Transient Sky <a class="header-anchor" href="#transient-sky" aria-label="Permalink to “Transient Sky”">​</a></h2><p>See what is changing in the sky now, and whether you can observe it.</p>',3)),a(r,{tool:"transient-sky"}),t[4]||(t[4]=o('<ul><li><strong>Feeds</strong>: gamma-ray bursts, neutrinos and gravitational waves from NASA&#39;s GCN, supernovae reported to the TNS and, on request, the ZTF stream through Fink.</li><li><strong>Verdict</strong>: each event is judged for the night, either against your <a href="./too-policies">ToO policies</a> or simply from the selected site. It is up now, observable later, too close to the Moon, or never up from here.</li><li><strong>Sort</strong>: choose the time window, show or hide missions, and apply a saved filter.</li><li><strong>Act</strong>: open an event for its details, import it as a target, or open its finding chart.</li></ul><p>Transient Sky is for browsing. What makes a telescope react by itself is in <a href="./too-policies">Targets of Opportunity</a>.</p><h2 id="finding-chart-editor" tabindex="-1">Finding Chart Editor <a class="header-anchor" href="#finding-chart-editor" aria-label="Permalink to “Finding Chart Editor”">​</a></h2><p>Prepare the chart you will recognise the field with, as your own instrument sees it.</p>',4)),a(r,{tool:"fdc-editor"}),t[5]||(t[5]=e("ul",null,[e("li",null,[e("strong",null,"Background"),i(": any Aladin survey, with its colour map, grid and reticle.")]),e("li",null,[e("strong",null,"Overlays"),i(": the field of view of your own instruments, computed from the equipment you registered, of large professional instruments, or one you draw: frame, circle or mosaic.")]),e("li",null,[e("strong",null,"Starlink"),i(": indicative tracks crossing the field on a given night. They are never included in saved charts.")]),e("li",null,[e("strong",null,"Save"),i(": a chart is attached to its target, and shows up in the Night Explorer and the Observer Console.")])],-1))])}const y=n(d,[["render",g]]);export{b as __pageData,y as default};
